        foreach(int length in new[]{4194303,4194304,4194305}) Add("C/byte-limit-"+length,CatalogAuthority,()=>{string p=Path.Combine(work,"large.osu");using(var f=File.Create(p))f.SetLength(length);if(length<=4194304)Eq(ChartFingerprint.Read(p).Bytes.Length,length);else Throws<InvalidDataException>(()=>ChartFingerprint.Read(p));});
