        Add("C/reparse-ancestry",CatalogAuthority,()=>{string target=Path.Combine(work,"target"),link=Path.Combine(work,"junction");Directory.CreateDirectory(target);string file=Path.Combine(target,"a.osu");File.WriteAllText(file,Text());var start=new ProcessStartInfo("cmd.exe"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};start.ArgumentList.Add("/c");start.ArgumentList.Add("mklink");start.ArgumentList.Add("/J");start.ArgumentList.Add(link);start.ArgumentList.Add(target);using var process=Process.Start(start)!;string output=process.StandardOutput.ReadToEnd()+process.StandardError.ReadToEnd();process.WaitForExit();Eq(process.ExitCode,0,"create isolated junction: "+output);try{Throws<InvalidDataException>(()=>CatalogPaths.Canonical(link));Throws<InvalidDataException>(()=>CatalogPaths.Canonical(Path.Combine(link,"a.osu")));Eq(LocalChartCatalog.Index(Path.Combine(link,"a.osu")).Availability,ChartAvailability.Invalid);}finally{Directory.Delete(link);}});
