    static void Identity()
    {
        const string A="E043 P14-P16/P20/P22/P26; R16 length/time/SHA256 revision policy ENGINEERING";
        Add("I/exact-path",A,()=>{string p=Put();var a=LocalChartCatalog.Index(p);Eq(a.Path,Path.GetFullPath(p));Eq(a.Fingerprint!.Length,new FileInfo(p).Length);Eq(a.Fingerprint.Sha256,Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(p))));a.Verify();});
        Add("I/windows-path-case",A,()=>{Yes(OperatingSystem.IsWindows(),"Windows-specific identity control");string p=Put();Eq(CatalogPaths.Comparer.Equals(p,p.ToUpperInvariant()),true);Eq(LocalChartCatalog.Index(p.ToUpperInvariant()).Fingerprint,LocalChartCatalog.Index(p).Fingerprint);});
        Async("I/unchanged-reference",A,async()=>{Put();using var c=new LocalChartCatalog([work]);var a=(await c.RefreshAsync())!.Charts[0];a.ReportGameplay(null);var b=(await c.RefreshAsync())!.Charts[0];Same(b,a);Eq(b.GameplayValidated,true);});
        foreach(string mutation in new[]{"content","length","time","hash-hidden-by-stamp"}) Async("I/revision-"+mutation,A,async()=>{string p=Put();using var c=new LocalChartCatalog([work]);var a=(await c.RefreshAsync())!.Charts[0];a.ReportGameplay(null);DateTime stamp=File.GetLastWriteTimeUtc(p);string text=File.ReadAllText(p);if(mutation=="time")File.SetLastWriteTimeUtc(p,stamp.AddSeconds(4));else if(mutation=="length")File.AppendAllText(p,"\n// extra length");else{File.WriteAllText(p,text.Replace("Finite artist","Other_ artist"));if(mutation=="hash-hidden-by-stamp")File.SetLastWriteTimeUtc(p,stamp);}var b=(await c.RefreshAsync())!.Charts[0];Different(b,a);Eq(b.GameplayValidated,false);Eq(b.GameplayError,null);Yes(b.Fingerprint!=a.Fingerprint,"revision changed");if(mutation=="hash-hidden-by-stamp"){Eq(b.Fingerprint!.Length,a.Fingerprint!.Length);Eq(b.Fingerprint.ModifiedUtcTicks,a.Fingerprint.ModifiedUtcTicks);Yes(b.Fingerprint.Sha256!=a.Fingerprint.Sha256,"SHA catches equal length/time");}Throws<InvalidDataException>(()=>a.Verify());});
        Async("I/delete-and-reintroduce",A,async()=>{string p=Put();using var c=new LocalChartCatalog([work]);var a=(await c.RefreshAsync())!.Charts[0];File.Delete(p);Eq((await c.RefreshAsync())!.Charts.Count,0);Throws<FileNotFoundException>(()=>a.Verify());Put();var b=(await c.RefreshAsync())!.Charts[0];Different(a,b);});
        Async("I/failed-revision-retry",A,async()=>{Put();using var c=new LocalChartCatalog([work]);var a=(await c.RefreshAsync())!.Charts[0];a.ReportGameplay("controlled parser failure");Eq(a.Available,false);Eq(a.GameplayValidated,false);var b=(await c.RefreshAsync())!.Charts[0];Different(b,a);Eq(b.GameplayError,null);Yes(b.Available,"fresh retry row");});
        Add("I/success-then-invalidated",A,()=>{var a=Chart();a.ReportGameplay(null);Eq(a.GameplayValidated,true);a.ReportGameplay("invalidated");Eq(a.GameplayValidated,false);Eq(a.Available,false);Eq(a.GameplayError,"invalidated");});
        Async("I/path-replaced-invalid",A,async()=>{string p=Put();using var c=new LocalChartCatalog([work]);var a=(await c.RefreshAsync())!.Charts[0];File.WriteAllText(p,"bad");var b=(await c.RefreshAsync())!.Charts[0];Different(a,b);Eq(b.Availability,ChartAvailability.Invalid);Eq(b.GameplayValidated,false);});
        Add("I/fresh-parser-per-load",A,()=>{var a=Chart();var x=a.LoadGameplay();var y=a.LoadGameplay();Different(x,y);Eq(x.Circles[0].Position,y.Circles[0].Position);});
        Add("I/cancel-fingerprint",A,()=>{string p=Put();using var stop=new CancellationTokenSource();stop.Cancel();Throws<OperationCanceledException>(()=>ChartFingerprint.Read(p,stop.Token));Throws<OperationCanceledException>(()=>LocalChartCatalog.Index(p,token:stop.Token));});
        Add("I/canonical-unc-rejected",A,()=>Throws<InvalidDataException>(()=>CatalogPaths.Canonical("\\\\qa14-invalid-server\\share\\a.osu")));
    }
